const raw = $input.first().json;
const body = raw.body || raw;
const event = body.event || body.type || raw.event || raw.type || '';
const instance = body.instance || raw.instance || '';

// Extraer objeto de datos (soporta data como objeto o array de Evolution API)
let data = body.data || raw.data || {};
if (Array.isArray(data)) {
  data = data[0] || {};
}

// Extraer remoteJid
const remoteJid = data.key?.remoteJid || body.key?.remoteJid || data.remoteJid || body.remoteJid || '';

// Filtrar grupos y transmisiones
const isGroupOrBroadcast = remoteJid.endsWith('@g.us') || remoteJid.includes('status@broadcast');

// Extraer y verificar si es mensaje propio (fromMe)
const rawFromMe = data.key?.fromMe ?? body.key?.fromMe ?? data.fromMe ?? body.fromMe;
const isFromMeRaw = rawFromMe === true || rawFromMe === 'true' || rawFromMe === 1;

// Se marca isFromMe si es propio o si viene de grupo/broadcast para ignorarlo
const isFromMe = isFromMeRaw || isGroupOrBroadcast;

// Nombre de contacto
const pushName = data.pushName || body.pushName || 'Jugador';

// Tipo de evento
const isConnectionUpdate = (event === 'connection.update' || event === 'CONNECTION_UPDATE');
const isMessageUpsert = (event === 'messages.upsert' || event === 'MESSAGES_UPSERT');

// Extraer texto del mensaje de cualquier estructura de WhatsApp
let messageText = '';
if (data.message) {
  messageText = data.message.conversation ||
                data.message.extendedTextMessage?.text ||
                data.message.imageMessage?.caption ||
                data.message.videoMessage?.caption ||
                data.message.documentMessage?.caption ||
                '';
} else if (body.messageText) {
  messageText = body.messageText;
}

// Respuesta a menú interactivo (lista nativa o botones)
const listRowId = data.message?.listResponseMessage?.singleSelectReply?.selectedRowId ||
                  data.message?.buttonsResponseMessage?.selectedButtonId ||
                  data.message?.templateButtonReplyMessage?.selectedId ||
                  '';
if (!messageText && data.message?.listResponseMessage) {
  messageText = data.message.listResponseMessage.title || '';
}

// Detectar si es media (imagen/documento/comprobante)
const isImage = !!(data.message?.imageMessage || data.message?.documentMessage);

// DETECCIÓN: Solo candidatos que piden reserva o interactúan con la reserva
const rawText = (messageText || '').toLowerCase().trim();
const isInteractiveAction = !!listRowId;
const isMedia = isImage;

// Palabras clave asociadas a reserva, canchas, horarios o pagos
const reservationRegex = /(reserv|cancha|pista|padel|pádel|futbol|fútbol|horario|turno|disponib|alquil|agend|separ|apart|precio|cuanto|cuánto|tarifa|costo|partido|jugar|pichanga|comprobante|transfer|banco|cuenta|menu|menú|servicio|opcion)/i;
const hasReservationKeywords = reservationRegex.test(rawText);

// Respuestas comunes en conversación activa (números de opción 1-4, confirmaciones, horas)
const activeFlowPattern = /^([1-4]|si|sí|ok|dale|listo|confirmo|confirmar|cancelar|no)$/i.test(rawText) ||
                          /\b(hoy|mañana|lunes|martes|miércoles|miercoles|jueves|viernes|sábado|sabado|domingo)\b/i.test(rawText) ||
                          /\b\d{1,2}(:\d{2})?\s*(am|pm)?\b/i.test(rawText);

const isReservationCandidate = isInteractiveAction || isMedia || hasReservationKeywords || activeFlowPattern;

return {
  json: {
    rawEvent: event,
    instance,
    isConnectionUpdate,
    isMessageUpsert,
    isFromMe,
    remoteJid,
    pushName,
    messageText,
    isImage,
    listRowId,
    isReservationCandidate,
    data
  }
};
